# frozen_string_literal: true

# Load encoding map if it exists (generated by font_builder.rb).
# When running tests, the test file stubs ENCODING_MAP before requiring this file.
unless defined?(ENCODING_MAP)
  require_relative '../encoding_map'
end

module Converter
  COMMAND_PATTERN = /\A-\w+-\r?\z/

  def self.command_string?(str)
    str.match?(COMMAND_PATTERN)
  end

  HIGHLIGHT_MARKER = '{hl}'
  HIGHLIGHT_CODE = 0x001
  NEWLINE_CODE   = 0x00D
  PAD_CODE       = 0x1FF

  # Encode a display string to an array of 9-bit tile codes using ENCODING_MAP.
  # \r becomes NEWLINE_CODE; {hl} becomes HIGHLIGHT_CODE. Missing chars abort.
  def self.encode_codes(str)
    result = []
    i = 0
    while i < str.length
      if str[i, HIGHLIGHT_MARKER.length] == HIGHLIGHT_MARKER
        result << HIGHLIGHT_CODE
        i += HIGHLIGHT_MARKER.length
      elsif str[i] == "\r"
        result << NEWLINE_CODE
        i += 1
      elsif ENCODING_MAP.key?(str[i])
        result << ENCODING_MAP[str[i]]
        i += 1
      else
        abort "ERROR: No tile mapping for character #{str[i].inspect} " \
              "(U+#{str[i].codepoints.first.to_s(16).upcase}). " \
              "Add it to demo04_data.txt's character set and rebuild font_data.h."
      end
    end
    result
  end

  # Pack 9-bit codes into 9-byte blocks: [mask][low0..low7] where mask
  # bit i carries code i's bit 8. The final block is padded with PAD_CODE.
  def self.pack_blocks(codes)
    padded = codes.dup
    padded << PAD_CODE while padded.length % 8 != 0
    out = String.new(encoding: 'BINARY')
    padded.each_slice(8) do |slice|
      mask = 0
      slice.each_with_index { |c, i| mask |= ((c >> 8) & 1) << i }
      out << mask.chr
      slice.each { |c| out << (c & 0xFF).chr }
    end
    out
  end

  def self.pack_string(str)
    pack_blocks(encode_codes(str))
  end

  # Format a binary string as a Ruby string literal with \xNN escapes for all bytes.
  def self.format_string(str)
    escaped = str.bytes.map { |b| "\\x%02X" % b }.join
    "\"#{escaped}\""
  end
end

# Main script — only runs when invoked directly, not when required by tests
if __FILE__ == $0
  abort "Usage: converter.rb <text_file>" unless ARGV.size == 1

  File.open(ARGV[0], encoding: 'UTF-8') do |file|
    items = file.read.split(/^:/)
    items = items.reject(&:empty?).map { |i| i.gsub("\n", "\r") }

    pages = []
    current_page = []

    items.each do |item|
      if item.start_with?("=")
        pages.push current_page unless current_page.empty?
        current_page = [item.sub(/^=/, "")]
      else
        current_page.push(item)
      end
    end
    pages.push current_page unless current_page.empty?

    # Encode all display strings; pass command strings through as raw ASCII
    encoded_pages = pages.map do |page|
      page.map do |item|
        if Converter.command_string?(item.strip)
          (item.strip + "\r").inspect  # unused by current deck; passthrough kept
        else
          Converter.format_string(Converter.pack_string(item))
        end
      end
    end

    puts "pres_data ="
    # Emit the nested array manually to preserve \xNN escaping
    puts "["
    encoded_pages.each_with_index do |page, pi|
      print "  ["
      print page.join(", ")
      print "]"
      print "," unless pi == encoded_pages.size - 1
      puts
    end
    puts "]"
    puts
  end
end
